INSERT INTO catalog_feed_parts(tld,part,records) SELECT s.tld,s.part,s.records FROM domainradar_seed_stage s LEFT JOIN catalog_feeds c ON c.tld=s.tld WHERE s.part>0 AND (c.checked_at IS NULL OR s.checked_at>=c.checked_at) ON CONFLICT(tld,part) DO UPDATE SET records=excluded.records;
INSERT INTO catalog_feeds(tld,records,checked_at) SELECT tld,records,checked_at FROM domainradar_seed_stage WHERE part=0 ON CONFLICT(tld) DO UPDATE SET records=excluded.records,checked_at=excluded.checked_at WHERE excluded.checked_at>=catalog_feeds.checked_at;
